<?php
declare(strict_types=1);
require_once __DIR__.'/applications.php';
function life_application_public(array $r):array{if(isset($r['state'])){unset($r['state']['receipts']);foreach($r['state']['documents']??[] as $i=>$doc)unset($r['state']['documents'][$i]['text'],$r['state']['documents'][$i]['fileId']);}return $r;}
function life_application_route(LifeStore $store,string $method,string $action,array $input,array $config):never{
 $apps=new LifeApplications($store);
 if($method==='GET'&&$action==='applications'){ $r=$apps->read();life_json(life_application_public($r)+['statistics'=>LifeApplications::statistics($r['state'])]);}
 if($method==='GET'&&$action==='applications.search-suggestions'){$id=LifeApplications::id($_GET['id']??'');$widget=$_SESSION['applicationSearchWidgets'][$id]??null;if(!$widget||$widget['expires']<time())throw new LifeError('Search suggestions expired.',404);header('Content-Type: text/html; charset=utf-8');header('X-Frame-Options: SAMEORIGIN');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'self'; base-uri 'none'; form-action 'none'");echo '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>'.$widget['html'].'</body></html>';exit;}
 if($method==='GET'&&$action==='applications.document'){require_once __DIR__.'/application-documents.php';(new LifeApplicationDocuments($apps,$config))->download((string)($_GET['id']??''));}
 if($method!=='POST')throw new LifeError('Method not allowed.',405);
 if($action==='applications.mutate'){if(!is_int($input['version']??null)||!is_array($input['args']??null))throw new LifeError('Reload applications before saving.',409);$op=LifeStore::text($input['operation']??'',60,true);if($op==='document.add')throw new LifeError('Use the document upload or draft editor.',403);life_json(life_application_public($apps->mutate($input['version'],$op,$input['args'],(string)($input['requestId']??''))));}
 if($action==='applications.upload'){require_once __DIR__.'/application-documents.php';life_json(life_application_public((new LifeApplicationDocuments($apps,$config))->upload($input)));}
 if(in_array($action,['applications.research','applications.tailor'],true)){require_once __DIR__.'/application-ai.php';$ai=new LifeApplicationAI($apps);life_json($action==='applications.research'?$ai->research($input):$ai->tailor($input));}
 if($action==='applications.draft'){if(($input['reviewed']??false)!==true)throw new LifeError('Review the draft before saving it.',403);require_once __DIR__.'/application-documents.php';$docs=new LifeApplicationDocuments($apps,$config);life_json(life_application_public(($input['format']??'text')==='word'?$docs->saveWord((int)($input['version']??0),$input):$docs->saveText((int)($input['version']??0),$input)));}
 if(str_starts_with($action,'applications.google.')){require_once __DIR__.'/application-google.php';$google=new LifeApplicationGoogle($apps);if($action==='applications.google.status')life_json($google->status());if($action==='applications.google.disconnect'){$google->disconnect();life_json(['ok'=>true]);}if($action==='applications.google.export')life_json($google->export($input));}
 if($action==='applications.task'){
  $snapshot=$apps->read();$id=LifeApplications::id($input['id']??'');$o=LifeApplications::find($snapshot['state'],'opportunities',$id,true);$key=LifeStore::text($input['requestId']??'',100,true);foreach($snapshot['state']['receipts'] as $r)if($r['requestId']===$key){if($r['operation']!=='opportunity.save'||$r['recordId']!==$id)throw new LifeError('This request belongs to another application.',409);life_json(life_application_public($snapshot)+['board'=>$store->read(),'receipt'=>$r]);}
  if($snapshot['version']!==($input['version']??null))throw new LifeError('Reload applications before linking a task.',409);$db=$store->db;$db->beginTransaction();try{$board=$store->read();$listId=$input['listId']??'';if($listId==='')foreach($board['state']['lists'] as $list)if(!$list['archived']&&!$list['isDone']){$listId=$list['id'];break;}$title=LifeStore::text($input['title']??'Prepare '.$o['title'],200,true);$next=$store->mutate($board['version'],'task.save',['title'=>$title,'listId'=>$listId,'dueDate'=>LifeApplications::date($input['date']??''),'dueTime'=>$input['time']??'','reminderMinutes'=>$input['reminderMinutes']??null,'notes'=>'Application: '.$o['title'].' · '.$o['organisation']]);$ids=array_values(array_diff(array_column($next['state']['tasks'],'id'),array_column($board['state']['tasks'],'id')));if(count($ids)!==1)throw new LifeError('The task save could not be verified.',503);$saved=$apps->mutate($snapshot['version'],'opportunity.save',['id'=>$id,'taskIds'=>array_merge($o['taskIds'],$ids)],$key);$db->commit();LifeGoogleSync::enqueue($store);life_json(life_application_public($saved)+['board'=>$store->read(),'taskId'=>$ids[0]]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
 }
 throw new LifeError('Unknown application request.',404);
}
